code2='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            minr = min(y for y,x in cells); minc = min(x for y,x in cells)
            shape = frozenset((y-minr, x-minc) for y,x in cells)
            objects.append((color, cells, shape))
    reference_colors = {}
    for color, cells, shape in objects:
        if color != 1:
            reference_colors.setdefault(shape, set()).add(color)
    for color, cells, shape in objects:
        if color == 1 and shape in reference_colors:
            target = sorted(reference_colors[shape])[0]
            for r, c in cells:
                out[r][c] = target
    return out
'''
